  "grammatik|konjunktiv2-vergangenheit": [{"type":"order","answer":"Du hättest mir das ruhig sagen können","hint":"Beginne mit „Du\".","explain":"Mit Modalverb: hätte + Infinitiv + Modalverb im Infinitiv."},{"type":"order","answer":"An deiner Stelle hätte ich das nicht gemacht","hint":"Beginne mit „An\".","explain":"An deiner Stelle … — der klassische Rat im Rückblick."},{"type":"order","answer":"Beinahe hätte ich den Zug verpasst","hint":"Beginne mit „Beinahe\".","explain":"beinahe / fast + Konjunktiv II: es ist gerade noch gut gegangen."},{"type":"order","answer":"Ich hätte nie gedacht, dass das so lange dauert","hint":"Beginne mit „Ich\".","explain":"hätte gedacht — der überraschte Rückblick."},{"type":"order","answer":"Das wäre nicht nötig gewesen","hint":"Beginne mit „Das\".","explain":"sein + Adjektiv im Rückblick: wäre … gewesen."},{"type":"order","answer":"Wenn es nicht geregnet hätte, wären wir spazieren gegangen","hint":"Beginne mit „Wenn\".","explain":"regnen bildet das Perfekt mit haben."},{"type":"order","answer":"Ohne deine Hilfe hätte ich das nie geschafft","hint":"Beginne mit „Ohne\".","explain":"Ohne … — die Bedingung steht ohne wenn."},{"type":"order","answer":"Es hätte auch ganz anders kommen können","hint":"Beginne mit „Es\".","explain":"hätte … können: die Möglichkeit, die es nicht geworden ist."}],
  "grammatik|lassen": [{"type":"order","answer":"Meine Eltern lassen mich abends nicht mehr allein weggehen","hint":"Beginne mit „Meine\".","explain":"Hier heißt lassen: erlauben — oder eben nicht erlauben."},{"type":"order","answer":"Das Fenster lässt sich nicht öffnen","hint":"Beginne mit „Das\".","explain":"sich lassen + Infinitiv heißt: Es ist nicht möglich. Ersatz für: kann nicht geöffnet werden."},{"type":"order","answer":"Ich habe meinen Schlüssel zu Hause gelassen","hint":"Beginne mit „Ich\".","explain":"Ohne zweites Verb heißt das Partizip gelassen."},{"type":"order","answer":"Ich habe mir die Haare schneiden lassen","hint":"Beginne mit „Ich\".","explain":"Steht ein zweites Verb dabei, heißt es im Perfekt lassen statt gelassen."},{"type":"order","answer":"Der Fehler lässt sich leicht erklären","hint":"Beginne mit „Der\".","explain":"sich lassen: Das kann man leicht erklären."},{"type":"order","answer":"Bitte lassen Sie mich kurz ausreden","hint":"Beginne mit „Bitte\".","explain":"Höfliche Bitte um Erlaubnis: Erlauben Sie mir, zu Ende zu sprechen."}],
  "grammatik|modalpartikeln": [{"type":"order","answer":"Komm mal her, ich zeig dir was","hint":"Beginne mit „Komm\".","explain":"mal macht die Aufforderung klein und freundlich. Ohne mal klingt derselbe Satz wie ein Befehl."},{"type":"order","answer":"Du weißt ja, wie das hier läuft","hint":"Beginne mit „Du\".","explain":"ja heißt: Das wissen wir beide schon, ich sage nichts Neues."},{"type":"order","answer":"Dann fahren wir eben mit dem Bus","hint":"Beginne mit „Dann\".","explain":"eben und halt sagen: Es ist, wie es ist — da kann man nichts machen."},{"type":"order","answer":"Er wird wohl im Stau stehen","hint":"Beginne mit „Er\".","explain":"wohl drückt eine Vermutung aus, ohne dass man vermuten sagen muss."},{"type":"order","answer":"Setz dich doch hin, du stehst da schon zehn Minuten","hint":"Beginne mit „Setz\".","explain":"doch und mal machen aus der Aufforderung eine Einladung."},{"type":"order","answer":"Das habe ich dir doch gesagt","hint":"Beginne mit „Das\".","explain":"Hier erinnert doch an etwas, das schon einmal gesagt wurde."},{"type":"order","answer":"Ruf mich einfach an, wenn du da bist","hint":"Beginne mit „Ruf\".","explain":"einfach nimmt der Bitte das Schwere: Es ist kein Aufwand."}],
  "grammatik|modalverben": [{"type":"order","answer":"Hier darf man nicht rauchen","hint":"Beginne mit „Hier\".","explain":"dürfen = erlaubt sein. Mit nicht: verboten."},{"type":"order","answer":"Ich möchte gern einen Kaffee, bitte","hint":"Beginne mit „Ich\".","explain":"möchte = höflicher Wunsch."},{"type":"order","answer":"Meine Chefin sagt, ich soll das Protokoll schreiben","hint":"Beginne mit „Meine\".","explain":"sollen = jemand anders will es so."},{"type":"order","answer":"Mit dem Ticket kannst du auch die S-Bahn benutzen","hint":"Beginne mit „Mit\".","explain":"können = Möglichkeit."},{"type":"order","answer":"Kinder unter zwölf dürfen vorne nicht sitzen","hint":"Beginne mit „Kinder\".","explain":"Regel/Verbot → dürfen nicht."}],
  "grammatik|modalverben-subjektiv": [{"type":"order","answer":"Das könnte stimmen, ich bin mir aber nicht sicher","hint":"Beginne mit „Das\".","explain":"können subjektiv: eine von mehreren Möglichkeiten."},{"type":"order","answer":"Das Restaurant soll sehr gut sein, habe ich gehört","hint":"Beginne mit „Das\".","explain":"Die Empfehlung aus zweiter Hand."},{"type":"order","answer":"Sie dürfte inzwischen angekommen sein, der Flug war pünktlich","hint":"Beginne mit „Sie\".","explain":"dürfte: eine vorsichtige, aber begründete Vermutung."},{"type":"order","answer":"Der Termin soll verschoben worden sein, ich habe nichts Genaues gehört","hint":"Beginne mit „Der\".","explain":"sollen + Passiv-Perfekt-Infinitiv: Hörensagen über etwas Vergangenes."}],
