  "grammatik|passiv-b2": [{"type":"order","answer":"Der Antrag wurde gestern geprüft","hint":"Beginne mit „Der\".","explain":"Passiv im Präteritum: wurde + Partizip II."},{"type":"order","answer":"Die Rechnung wird noch heute bezahlt","hint":"Beginne mit „Die\".","explain":"Passiv im Präsens: wird + Partizip II."},{"type":"order","answer":"Das Formular wird von der Sachbearbeiterin unterschrieben","hint":"Beginne mit „Das\".","explain":"Wer es tut, steht mit von — nötig ist das aber selten."},{"type":"order","answer":"Die Wohnung ist letzte Woche renoviert worden","hint":"Beginne mit „Die\".","explain":"Passiv im Perfekt endet auf worden, nicht auf geworden."},{"type":"order","answer":"In diesem Raum wird nicht geraucht","hint":"Beginne mit „In\".","explain":"Ohne handelnde Person: das unpersönliche Passiv."},{"type":"order","answer":"Der Termin muss leider verschoben werden","hint":"Beginne mit „Der\".","explain":"Modalverb + Partizip II + werden."},{"type":"order","answer":"Die Unterlagen müssen bis Freitag eingereicht werden","hint":"Beginne mit „Die\".","explain":"Konjugiert wird das Modalverb, nicht werden."},{"type":"order","answer":"Das Paket wird morgen früh geliefert","hint":"Beginne mit „Das\".","explain":"Zukunft im Passiv steht meist einfach im Präsens."},{"type":"order","answer":"Nach dem Unfall wurde die Straße für zwei Stunden gesperrt","hint":"Beginne mit „Nach\".","explain":"Der Vorgang liegt in der Vergangenheit: wurde."},{"type":"order","answer":"Die Ergebnisse werden nächste Woche bekannt gegeben","hint":"Beginne mit „Die\".","explain":"Plural: werden + Partizip II."}],
